package main

import (
	"context"
	"fmt"
)

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	ch := make(chan int)
	go func() { cancel() }() // trigger cancellation

	select {
	case v := <-ch:
		fmt.Println("value:", v)
	case <-ctx.Done(): // closed channel -> this case fires
		fmt.Println("stopped:", ctx.Err())
	}
	// Output: stopped: context canceled
}

package main

import (
	"context"
	"fmt"
	"time"
)

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Millisecond)
	defer cancel() // always release the timer

	select {
	case <-time.After(1 * time.Second): // slow work
		fmt.Println("work done")
	case <-ctx.Done(): // timer fires first
		fmt.Println(ctx.Err())
	}
	// Output: context deadline exceeded
}

