	"fmt"
)

func main() {
	parent, cancelParent := context.WithCancel(context.Background())
	child, cancelChild := context.WithCancel(parent) // child derived from parent
	defer cancelChild()

	cancelParent() // cancelling the parent...
	<-child.Done()  // ...also cancels the child
	fmt.Println(child.Err()) // Output: context canceled
}

package main

import (
	"context"
	"fmt"
	"time"
)

func handle(parent context.Context) {
	ctx, cancel := context.WithTimeout(parent, time.Second)
	defer cancel() // releases the timer the instant handle returns, even if work finished early
	doWork(ctx)
}

func doWork(ctx context.Context) { _ = ctx }

func main() {
	handle(context.Background())
	fmt.Println("no leaked timer") // Output: no leaked timer
}

package main

import (
	"context"
	"fmt"
)

// ctx is the FIRST parameter, passed onward rather than stored.
func Fetch(ctx context.Context, url string) (string, error) {
	if err := ctx.Err(); err != nil {
		return "", err // respect cancellation before doing I/O
	}
	return "body of " + url, nil
}

func main() {
	body, err := Fetch(context.Background(), "/api")
	fmt.Println(body, err) // Output: body of /api <nil>
}

