package main

import (
	"context"
	"fmt"
	"time"
)

func worker(ctx context.Context) error {
	for i := 0; i < 5; i++ {
		select {
		case <-ctx.Done(): // cancelled/timed out -> stop now
			return ctx.Err()
		case <-time.After(50 * time.Millisecond): // simulate a step
			fmt.Println("step", i)
		}
	}
	return nil
}

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 120*time.Millisecond)
	defer cancel()
	fmt.Println("err:", worker(ctx)) // stops around step 1, returns deadline exceeded
}

