func fetch(ctx context.Context) (string, error) {
	result := make(chan string, 1) // BUFFERED: send never blocks
	go func() {
		time.Sleep(2 * time.Second)
		result <- "data" // succeeds into the buffer even if we already returned
	}()
	select {
	case r := <-result:
		return r, nil
	case <-ctx.Done():
		return "", ctx.Err() // goroutine can still complete & exit -> no leak
	}
}

func WaitFirst(ctx context.Context, ch <-chan int) (int, error) {
	select {
	case v := <-ch: // a value arrived first
		return v, nil
	case <-ctx.Done(): // cancelled/timed out first
		return 0, ctx.Err()
	}
}

func RetryWithContext(ctx context.Context, attempts int, f func(context.Context) error) error {
	var lastErr error
	backoff := 10 * time.Millisecond
	for i := 0; i < attempts; i++ {
		if err := ctx.Err(); err != nil {
			return err // cancelled before this attempt
		}
		if lastErr = f(ctx); lastErr == nil {
			return nil // success
		}
		if i == attempts-1 {
			break // no wait after the final attempt
		}
		timer := time.NewTimer(backoff)
		select {
		case <-timer.C: // backoff elapsed -> retry
		case <-ctx.Done(): // cancelled during backoff -> abort
			timer.Stop() // release the timer
			return ctx.Err()
		}
		backoff *= 2 // exponential
	}
	return lastErr
}
